"""Strengthen the existing UI journey without changing the action fixture."""
import pathlib
p=pathlib.Path(__file__).resolve().parents[1]/'scripts/test-content-r20-e2e.js'
s=p.read_text(encoding='utf-8')
def rep(old,new):
 global s
 assert old in s,old[:100]
 s=s.replace(old,new)
rep("const runtimeFiles=['package.json'", "const runtimeFiles=['scripts/test-content-r20-e2e.js','scripts/r22-software-renderer-preload.js','package.json'")
rep("const labelRect=showing(label)?label.getBoundingClientRect():null,ringRect=showing(ring)?ring.getBoundingClientRect():null;", "const labelRect=showing(label)?label.getBoundingClientRect():null,ringRect=showing(ring)?ring.getBoundingClientRect():null;\n  const scenery=[...document.querySelectorAll('.ob[data-kind=structure],.ob[data-kind=tea-porch],.ob[data-kind=building],.world-site,.farm-gathering,.farm-memory')].filter(showing);\n  const wasHidden=ring.hidden;ring.hidden=false;const targetRing=ring.getBoundingClientRect();ring.hidden=wasHidden;")
rep("return{phase,viewport:", "return{phase,inlineArrow:getComputedStyle(document.querySelector('.carry-distance'),'::after').content,targetInScene:targetRing.right>bounds.left&&targetRing.left<bounds.right&&targetRing.bottom>bounds.top&&targetRing.top<bounds.bottom,goalLabelSceneOverlaps:labelRect?scenery.filter(e=>overlaps(labelRect,e.getBoundingClientRect())).map(e=>e.className+':'+(e.dataset.projectId||e.dataset.kind||'')):[],viewport:")
rep("row.phase==='walking'&&row.goalRingInScene", "row.phase==='walking'&&row.targetInScene")
rep("row.goalLabelHudOverlaps===0&&row.goalLabel.rect.x", "row.goalLabelHudOverlaps===0&&row.goalLabelSceneOverlaps.length===0&&row.goalLabel.rect.x")
rep("row.routeLabelAria.includes('\\u7ad9\\u9019\\u88e1\\u4ea4\\u7c43')", "row.routeLabelAria.includes('沿路線走近交籃')")
rep("if(row.phase==='reach')check", "if(['reach','contact','reply'].includes(row.phase))check(['none','normal','\"\"'].includes(row.inlineArrow),name+' inline direction arrow retired after arrival');\n  if(row.phase==='reach')check")
rep("await snap(p,`phone-basket-${id}-near.png`);", "await snap(p,`phone-basket-${id}-near.png`);if(process.env.FARM_R22&&id==='elder'){const probe=await p.evaluate(async()=>{const scene=document.querySelector('#mapScene').getBoundingClientRect(),e=document.createElement('div');e.className='world-site';e.dataset.r22Probe='fallback';e.style.cssText=`position:fixed;left:${scene.left}px;top:${scene.top}px;width:${scene.width}px;height:${scene.height}px;pointer-events:none;opacity:0`;document.body.appendChild(e);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const label=document.querySelector('.carry-label'),r=label.getBoundingClientRect(),result={cue:label.dataset.r21StationCue,aria:label.getAttribute('aria-label'),content:getComputedStyle(label,'::before').content,inside:r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight,hidden:document.querySelector('.delivery-goal-label').hidden};e.remove();await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return result;});(report.fallbackProbes||=[]).push(probe);check(probe.cue==='true'&&probe.aria.includes('沿路線走近交籃')&&probe.content.includes('沿路線走近交籃')&&probe.inside&&probe.hidden,'occluded landing retains a truthful, in-viewport route fallback (DOM-only obstacle probe)');}")
rep("const reserve=await p.locator('.reserve-journal').innerText();check(await p.locator('.reserve-journal').count()===1&&reserve.includes('\\u4e0b\\u6b21\\u9080\\u8acb\\u5148\\u9810\\u7559')&&reserve.includes('\\u9178\\u5473\\u91ce\\u8393')&&reserve.includes('\\u9080\\u8acb\\u5c0d\\u8c61\\u5c1a\\u672a\\u6307\\u5b9a')&&reserve.includes('\\u98df\\u6750\\u7528\\u91cf\\uff1a'),'journal separates the prior serving from the next invitation reserve');", "const supply=await p.locator('.supply-history').innerText(),balances=await p.locator('[data-remaining-taste]').evaluateAll(es=>es.map(e=>({taste:e.dataset.remainingTaste,remaining:Number(e.dataset.remaining)}))),authority=await p.evaluate(()=>AdventureAPI.gatheringPortions(__farm.state(),Date.now()).map(p=>({taste:p.taste,remaining:p.remaining})));check(JSON.stringify(balances)===JSON.stringify(authority)&&balances.every(p=>p.remaining===0),'UI portions match authority: sour 1+1-2=0 and all three portions exhausted');check(supply.includes('本次聚餐的補備與剩餘')&&supply.includes('補備時已取用')&&!/下次邀請先預留|邀請對象尚未指定/.test(supply),'journal identifies spent refill as this-meal history');check(await p.locator('.invitation-status').getAttribute('data-invitation')==='none','journal shows actual invitation is not yet made');")
rep("const before=await p.evaluate(()=>__farm.state().adventure.gathering.servings.length);", "const before=await p.evaluate(()=>__farm.state().adventure.gathering.servings.length);")
rep("if(phase!=='received')check", "if(phase==='received')check((await p.locator('.gather-shared').innerText()).includes('接到手邊')&&!/喝一口茶|高高舉手/.test(await p.locator('.gather-shared').innerText()),id+' received caption names only the actual plate handover');if(phase!=='received')check")
rep("await p.locator('#gatherInvite').click();await p.locator('[data-invite=child]').click();await p.locator('#inviteConfirm').click();await snap", "const invitationResources=await resources(p);await p.locator('#gatherInvite').click();await p.locator('[data-invite=child]').click();await p.locator('#inviteConfirm').click();check(await resources(p)===invitationResources,'first invitation uses the shared plate without taking more materials');await p.locator('#inviteConfirm').dispatchEvent('click');check(await resources(p)===invitationResources,'repeated confirmation does not take materials');await snap")
rep("await snap(p,'phone-journal-invite-child-reloaded.png');", "check(await p.locator('.invitation-status').getAttribute('data-invitation')==='child'&&(await p.locator('.invitation-status').innerText()).includes('已邀圖圖'),'reloaded journal names the actual invited child');check(await resources(p)===invitationResources,'invitation reload preserves every material');await snap(p,'phone-journal-invite-child-reloaded.png');")
p.write_text(s,encoding='utf-8')
print('R22 UI journey checks updated')
